/* Flash-backed OctoBara assets generated by tools/stage4/make_octobara_frames.py. */
    .section .rodata.octobara,"a",@progbits
    .balign 4
    .global octobara_frames
    .type octobara_frames, @object
octobara_frames:
    .incbin "octobara.rgb565"
    .size octobara_frames, .-octobara_frames
    .global octobara_frames_end
octobara_frames_end:

    .balign 4
    .global octobara_rec_badge
    .type octobara_rec_badge, @object
octobara_rec_badge:
    .incbin "octobara_rec.rgb565"
    .size octobara_rec_badge, .-octobara_rec_badge
    .if (. - octobara_rec_badge) != (96 * 96 * 2)
    .error "Unexpected OctoBara recording badge size"
    .endif
